package com.bank.monthly;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MonthlyBalanceDemo {
    private static final Logger log = Logger.getLogger(MonthlyBalanceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        MonthlyBalanceService svc = new MonthlyBalanceService();

        // Defaults: int[] = 0, boolean[] = false, String[] = null.
        int[] counts = new int[3];
        boolean[] flags = new boolean[2];
        String[] names = new String[2];
        log.info(() -> "int[] defaults   = " + Arrays.toString(counts));
        log.info(() -> "boolean[] default= " + Arrays.toString(flags));
        log.info(() -> "String[] default = " + Arrays.toString(names));

        // Reference array defaults to null — must populate before use.
        BigDecimal[] year = svc.blankYear();
        log.warning(() -> "fresh BigDecimal[] month 0 = " + year[0] + " (null!)");

        // Populate month by month, then sum safely.
        for (int i = 0; i < year.length; i++) {
            year[i] = rajesh.getBalance().add(new BigDecimal(i * 1000));
        }
        BigDecimal total = svc.sum(year);
        log.info(() -> "year total = " + total);

        // Initializer form both creates and fills.
        BigDecimal[] opening = svc.seedOpening();
        log.info(() -> "seeded opening length = " + opening.length
                + ", first = " + opening[0]);

        // length is a FIELD, not a method (contrast size()/length()).
        log.fine(() -> "year.length = " + year.length);
    }
}

