class MonthlyBalanceService {
    private static final Logger log = Logger.getLogger(MonthlyBalanceService.class.getName());
    private static final int MONTHS = 12;

    // new form: 12 slots, every element defaults to null (reference type).
    BigDecimal[] blankYear() {
        return new BigDecimal[MONTHS];
    }

    // Initializer form: creates AND fills in one expression.
    BigDecimal[] seedOpening() {
        return new BigDecimal[] {
                new BigDecimal("1000000.00"), new BigDecimal("1001000.00"),
                new BigDecimal("1002000.00")
        };
    }

    // Sum safely, skipping any still-null (unpopulated) month.
    BigDecimal sum(BigDecimal[] months) {
        BigDecimal total = BigDecimal.ZERO;
        for (BigDecimal m : months) {
            if (m == null) {
                log.warning("Null month skipped during sum");
                continue;
            }
            total = total.add(m);
        }
        return total;
    }
}

